local ForgeSparkShieldMaker = {}
local PRODUCTS = {
    iron_forgesparkshield = { name = "Železni ščit za iskre", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ščit za iskre za kovace." },
    bronze_forgesparkshield = { name = "Bronast ščit za iskre", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ščit za iskre za kovace." },
    silver_forgesparkshield = { name = "Srebrn ščit za iskre", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn ščit za iskre za kovace." },
    gilded_forgesparkshield = { name = "Pozlačen ščit za iskre", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen ščit za iskre za kovace." },
    jewel_set_forgesparkshield = { name = "Draguljast ščit za iskre", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast ščit za iskre za kovace." },
    royal_sovereign_forgesparkshield = { name = "Kraljevski suveren ščit za iskre", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren ščit za iskre z biseri za krono." },
}
local BUILDINGS = {
    forgesparkshield_workshop = { name = "Forgesparkshield delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    forgesparkshield_house = { name = "Forgesparkshield hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_forgesparkshield_atelier = { name = "Mojstrski forgesparkshield atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_forgesparkshield_palace = { name = "Suverena forgesparkshield palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeSparkShieldMaker.ironStock=14; ForgeSparkShieldMaker.bronzeStock=12; ForgeSparkShieldMaker.woodStock=14; ForgeSparkShieldMaker.leatherStock=8; ForgeSparkShieldMaker.silverStock=8; ForgeSparkShieldMaker.goldStock=6; ForgeSparkShieldMaker.jewelStock=4; ForgeSparkShieldMaker.pearlStock=4
ForgeSparkShieldMaker.productStock = {}; ForgeSparkShieldMaker.buildings = {}; ForgeSparkShieldMaker.maker = nil; ForgeSparkShieldMaker.activeMaking = {}; ForgeSparkShieldMaker.totalProducts = 0; ForgeSparkShieldMaker.dayTimer = 0
function ForgeSparkShieldMaker.init() ForgeSparkShieldMaker.ironStock=14; ForgeSparkShieldMaker.bronzeStock=12; ForgeSparkShieldMaker.woodStock=14; ForgeSparkShieldMaker.leatherStock=8; ForgeSparkShieldMaker.silverStock=8; ForgeSparkShieldMaker.goldStock=6; ForgeSparkShieldMaker.jewelStock=4; ForgeSparkShieldMaker.pearlStock=4; ForgeSparkShieldMaker.productStock={}; ForgeSparkShieldMaker.buildings={}; ForgeSparkShieldMaker.maker=nil; ForgeSparkShieldMaker.activeMaking={}; ForgeSparkShieldMaker.totalProducts=0; ForgeSparkShieldMaker.dayTimer=0; print("[ForgeSparkShieldMaker] Royal Forge Spark Shield Maker System initialized (6 products, 4 buildings)") end
function ForgeSparkShieldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeSparkShieldMaker.maker={name=n or ("Ščitnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščitnik najet: %s (spretnost: %d)",ForgeSparkShieldMaker.maker.name,s),"success") end; return true end
function ForgeSparkShieldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeSparkShieldMaker.build(id) local ok,e=ForgeSparkShieldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeSparkShieldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeSparkShieldMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeSparkShieldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeSparkShieldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeSparkShieldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeSparkShieldMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeSparkShieldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeSparkShieldMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeSparkShieldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeSparkShieldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeSparkShieldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeSparkShieldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeSparkShieldMaker.buildings==0 then return false,"Potrebna ščitna delavnica" end; if not ForgeSparkShieldMaker.maker then return false,"Potreben scitnik" end; return true end
function ForgeSparkShieldMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeSparkShieldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeSparkShieldMaker.ironStock=ForgeSparkShieldMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeSparkShieldMaker.bronzeStock=ForgeSparkShieldMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeSparkShieldMaker.woodStock=ForgeSparkShieldMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeSparkShieldMaker.leatherStock=ForgeSparkShieldMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeSparkShieldMaker.silverStock=ForgeSparkShieldMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeSparkShieldMaker.goldStock=ForgeSparkShieldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeSparkShieldMaker.jewelStock=ForgeSparkShieldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeSparkShieldMaker.pearlStock=ForgeSparkShieldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeSparkShieldMaker.maker then t=math.max(1,t-math.floor(ForgeSparkShieldMaker.maker.skill/13)) end; table.insert(ForgeSparkShieldMaker.activeMaking,{id="forgesparkshield_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeSparkShieldMaker.completeMaking(m) local q=1.0+(ForgeSparkShieldMaker.getQualityBonus()/100); if ForgeSparkShieldMaker.maker then q=q+(ForgeSparkShieldMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeSparkShieldMaker.productStock[m.productType]=(ForgeSparkShieldMaker.productStock[m.productType] or 0)+m.quantity; ForgeSparkShieldMaker.totalProducts=ForgeSparkShieldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeSparkShieldMaker.maker then ForgeSparkShieldMaker.maker.itemsMade=ForgeSparkShieldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeSparkShieldMaker.maker.skill=math.min(100,ForgeSparkShieldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščit izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgesparkshield.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeSparkShieldMaker.update(dt) if not _G.state then return end; ForgeSparkShieldMaker.dayTimer=ForgeSparkShieldMaker.dayTimer+dt; if ForgeSparkShieldMaker.dayTimer>=30 then ForgeSparkShieldMaker.dayTimer=0; for i=#ForgeSparkShieldMaker.activeMaking,1,-1 do local m=ForgeSparkShieldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeSparkShieldMaker.completeMaking(m); table.remove(ForgeSparkShieldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeSparkShieldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeSparkShieldMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeSparkShieldMaker.getStats() return {ironStock=ForgeSparkShieldMaker.ironStock,bronzeStock=ForgeSparkShieldMaker.bronzeStock,woodStock=ForgeSparkShieldMaker.woodStock,leatherStock=ForgeSparkShieldMaker.leatherStock,silverStock=ForgeSparkShieldMaker.silverStock,goldStock=ForgeSparkShieldMaker.goldStock,jewelStock=ForgeSparkShieldMaker.jewelStock,pearlStock=ForgeSparkShieldMaker.pearlStock,productStock=ForgeSparkShieldMaker.productStock,numBuildings=#ForgeSparkShieldMaker.buildings,hasMaker=ForgeSparkShieldMaker.maker~=nil,makerName=ForgeSparkShieldMaker.maker and ForgeSparkShieldMaker.maker.name or "—",makerSkill=ForgeSparkShieldMaker.maker and ForgeSparkShieldMaker.maker.skill or 0,activeMaking=#ForgeSparkShieldMaker.activeMaking,totalProducts=ForgeSparkShieldMaker.totalProducts} end
return ForgeSparkShieldMaker
